{
  "kc_id": "KC_CLU_EVAL_002",
  "canonical_name": "SSE (Cluster Quality)",
  "definition": {
    "status": "grounded",
    "text": "Also known as scatter, the sum of the squared error (SSE) is an objective function used to measure the quality of a clustering; it is calculated by computing the error of each data point (its Euclidean distance to the closest centroid) and then computing the total sum of the squared errors.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "text": "In the context of K-means, a smaller SSE indicates that the prototypes (centroids) are a better representation of the points in their cluster; techniques such as K-means++ initialization can lead to better clustering results in terms of lower SSE.",
    "supporting_evidence_ids": [
      "E2",
      "E3"
    ],
    "abstention_reason": ""
  }
}

